import torch
import torch.nn as nn
import torch.nn.functional as F

from .blocks import (
    TimestepEmbedSequential,
    SpatialTransformer,
    Downsample,
    Upsample,
    ResBlock,
    AttentionBlock,
)
from .nn_util import (
    conv_nd,
    linear,
    zero_module,
    normalization,
    timestep_embedding,
    convert_module_to_f16, 
    convert_module_to_f32,
)


class UNetModel(nn.Module):
    """
    The full UNet model with attention and timestep embedding.
    :param in_channels: channels in the input Tensor.
    :param model_channels: base channel count for the model.
    :param out_channels: channels in the output Tensor.
    :param num_res_blocks: number of residual blocks per downsample.
    :param attention_resolutions: a collection of downsample rates at which
        attention will take place. May be a set, list, or tuple.
        For example, if this contains 4, then at 4x downsampling, attention
        will be used.
    :param dropout: the dropout probability.
    :param channel_mult: channel multiplier for each level of the UNet.
    :param conv_resample: if True, use learned convolutions for upsampling and
        downsampling.
    :param dims: determines if the signal is 1D, 2D, or 3D.
    :param use_checkpoint: use gradient checkpointing to reduce memory usage.
    :param num_heads: the number of attention heads in each attention layer.
    :param num_heads_channels: if specified, ignore num_heads and instead use
                               a fixed channel width per attention head.
    :param num_heads_upsample: works with num_heads to set a different number
                               of heads for upsampling. Deprecated.
    :param use_scale_shift_norm: use a FiLM-like conditioning mechanism.
    :param resblock_updown: use residual blocks for up/downsampling.
    :param use_new_attention_order: use a different attention pattern for potentially
                                    increased efficiency.
    """

    def __init__(
        self,
        in_channels,
        model_channels,
        out_channels,
        num_res_blocks,
        attention_resolutions,
        dropout=0,
        channel_mult=(1, 2, 4, 8),
        conv_resample=True,
        dims=3,
        use_checkpoint=False,
        use_fp16=False,
        num_heads=-1,
        num_head_channels=-1,
        num_heads_upsample=-1,
        use_scale_shift_norm=False,
        resblock_updown=False,
        use_new_attention_order=False,
        geometry_channels=0,
        map_channels=0,
        outpainting_channels=0,
        micro_channels=0,
        tag_channels=0,
        use_spatial_transformer=False,    # custom transformer support
        transformer_depth=1,              # custom transformer support
        context_dim=None,                 # custom transformer support
        n_embed=None,                     # custom support for prediction of discrete ids into codebook of first stage vq model
        legacy=False,
        level_spec=None,
        use_separate_color_head=False,    # Use separate output heads for geometry/color (direct diffusion only)
        **kwargs
    ):
        super().__init__()            
        if num_heads_upsample == -1:
            num_heads_upsample = num_heads

        if num_heads == -1:
            assert num_head_channels != -1, 'Either num_heads or num_head_channels has to be set'

        if num_head_channels == -1:
            assert num_heads != -1, 'Either num_heads or num_head_channels has to be set'

        self.in_channels = in_channels
        self.model_channels = model_channels
        self.out_channels = out_channels  # H channels (noise prediction)
        self.num_res_blocks = num_res_blocks
        self.attention_resolutions = attention_resolutions
        self.dropout = dropout
        self.channel_mult = channel_mult
        self.conv_resample = conv_resample
        self.use_checkpoint = use_checkpoint
        self.dtype = torch.float16 if use_fp16 else torch.float32
        self.num_heads = num_heads
        self.num_head_channels = num_head_channels
        self.num_heads_upsample = num_heads_upsample
        self.level_spec = level_spec
        self.predict_codebook_ids = n_embed is not None
        self.dims = dims
        
        # Store conditioning channel counts
        self.geometry_channels = geometry_channels
        self.map_channels = map_channels
        self.outpainting_channels = outpainting_channels
        self.inpainting_channels = kwargs.get('inpainting_channels', 0)
        self.micro_channels = micro_channels
        self.tag_channels = tag_channels
        
        actual_input_channels = in_channels + geometry_channels + map_channels + outpainting_channels + self.inpainting_channels + micro_channels + tag_channels

        time_embed_dim = model_channels * 4
        self.time_embed = nn.Sequential(
            linear(model_channels, time_embed_dim),
            nn.SiLU(),
            linear(time_embed_dim, time_embed_dim),
        )

        # Geometry embedding for FiLM conditioning (only if scale-shift norm enabled and geometry channels present)
        if use_scale_shift_norm and geometry_channels > 0:
            self.geo_embed = nn.Sequential(
                conv_nd(dims, geometry_channels, model_channels, 3, padding=1),
                nn.SiLU(),
                nn.AdaptiveAvgPool3d(1),
                nn.Flatten(),
                linear(model_channels, time_embed_dim),
            )
        else:
            self.geo_embed = None

        # Map embedding for FiLM conditioning (only if scale-shift norm enabled and map channels present)
        if use_scale_shift_norm and map_channels > 0:
            self.map_embed = nn.Sequential(
                conv_nd(dims, map_channels, model_channels, 3, padding=1),
                nn.SiLU(),
                nn.AdaptiveAvgPool3d(1),
                nn.Flatten(),
                linear(model_channels, time_embed_dim),
            )
        else:
            self.map_embed = None

        self.input_blocks = nn.ModuleList(
            [
                TimestepEmbedSequential(
                    conv_nd(dims, actual_input_channels, model_channels, 3, padding=1)
                )
            ]
        )
        self._feature_size = model_channels
        input_block_chans = [model_channels]
        ch = model_channels
        ds = 1
        for level, mult in enumerate(channel_mult):
            for _ in range(num_res_blocks):
                layers = [
                    ResBlock(
                        ch,
                        time_embed_dim,
                        dropout,
                        out_channels=mult * model_channels,
                        dims=dims,
                        use_checkpoint=use_checkpoint,
                        use_scale_shift_norm=use_scale_shift_norm,
                    )
                ]
                ch = mult * model_channels
                if ds in attention_resolutions:
                    if num_head_channels == -1:
                        dim_head = ch // num_heads
                    else:
                        num_heads = ch // num_head_channels
                        dim_head = num_head_channels
                    if legacy:
                        dim_head = ch // num_heads if use_spatial_transformer else num_head_channels
                    layers.append(
                        AttentionBlock(
                            ch,
                            use_checkpoint=use_checkpoint,
                            num_heads=num_heads,
                            num_head_channels=dim_head,
                            use_new_attention_order=use_new_attention_order,
                        ) if not use_spatial_transformer else SpatialTransformer(
                            ch, num_heads, dim_head, depth=transformer_depth, context_dim=context_dim
                        )
                    )
                self.input_blocks.append(TimestepEmbedSequential(*layers))
                self._feature_size += ch
                input_block_chans.append(ch)
            if level != len(channel_mult) - 1:
                out_ch = ch
                self.input_blocks.append(
                    TimestepEmbedSequential(
                        ResBlock(
                            ch,
                            time_embed_dim,
                            dropout,
                            out_channels=out_ch,
                            dims=dims,
                            use_checkpoint=use_checkpoint,
                            use_scale_shift_norm=use_scale_shift_norm,
                            down=True,
                        )
                        if resblock_updown
                        else Downsample(
                            ch, conv_resample, dims=dims, out_channels=out_ch
                        )
                    )
                )
                ch = out_ch
                input_block_chans.append(ch)
                ds *= 2
                self._feature_size += ch

        if num_head_channels == -1:
            dim_head = ch // num_heads
        else:
            num_heads = ch // num_head_channels
            dim_head = num_head_channels
        if legacy:
            #num_heads = 1
            dim_head = ch // num_heads if use_spatial_transformer else num_head_channels
        self.middle_block = TimestepEmbedSequential(
            ResBlock(
                ch,
                time_embed_dim,
                dropout,
                dims=dims,
                use_checkpoint=use_checkpoint,
                use_scale_shift_norm=use_scale_shift_norm,
            ),
            AttentionBlock(
                ch,
                use_checkpoint=use_checkpoint,
                num_heads=num_heads,
                num_head_channels=dim_head,
                use_new_attention_order=use_new_attention_order,
            ) if not use_spatial_transformer else SpatialTransformer(
                            ch, num_heads, dim_head, depth=transformer_depth, context_dim=context_dim
                        ),
            ResBlock(
                ch,
                time_embed_dim,
                dropout,
                dims=dims,
                use_checkpoint=use_checkpoint,
                use_scale_shift_norm=use_scale_shift_norm,
            ),
        )
        self._feature_size += ch

        self.output_blocks = nn.ModuleList([])
        for level, mult in list(enumerate(channel_mult))[::-1]:
            for i in range(num_res_blocks + 1):
                ich = input_block_chans.pop()
                layers = [
                    ResBlock(
                        ch + ich,
                        time_embed_dim,
                        dropout,
                        out_channels=model_channels * mult,
                        dims=dims,
                        use_checkpoint=use_checkpoint,
                        use_scale_shift_norm=use_scale_shift_norm,
                    )
                ]
                ch = model_channels * mult
                if ds in attention_resolutions:
                    if num_head_channels == -1:
                        dim_head = ch // num_heads
                    else:
                        num_heads = ch // num_head_channels
                        dim_head = num_head_channels
                    if legacy:
                        #num_heads = 1
                        dim_head = ch // num_heads if use_spatial_transformer else num_head_channels
                    layers.append(
                        AttentionBlock(
                            ch,
                            use_checkpoint=use_checkpoint,
                            num_heads=num_heads_upsample,
                            num_head_channels=dim_head,
                            use_new_attention_order=use_new_attention_order,
                        ) if not use_spatial_transformer else SpatialTransformer(
                            ch, num_heads, dim_head, depth=transformer_depth, context_dim=context_dim
                        )
                    )
                if level and i == num_res_blocks:
                    out_ch = ch
                    layers.append(
                        ResBlock(
                            ch,
                            time_embed_dim,
                            dropout,
                            out_channels=out_ch,
                            dims=dims,
                            use_checkpoint=use_checkpoint,
                            use_scale_shift_norm=use_scale_shift_norm,
                            up=True,
                        )
                        if resblock_updown
                        else Upsample(ch, conv_resample, dims=dims, out_channels=out_ch)
                    )
                    ds //= 2
                self.output_blocks.append(TimestepEmbedSequential(*layers))
                self._feature_size += ch

        # Separate output heads for geometry and color (only for direct diffusion with color)
        # This allows different optimization dynamics for each modality
        self.use_separate_color_head = use_separate_color_head and out_channels > 1
        
        if self.use_separate_color_head:
            self.color_channels = out_channels - 1  # Typically 3 for RGB
            self.geometry_out_channels = 1
            
            # Geometry head: predicts geometry epsilon
            self.out_geometry = nn.Sequential(
                normalization(ch),
                nn.SiLU(),
                zero_module(conv_nd(dims, model_channels, self.geometry_out_channels, 3, padding=1)),
            )
            
            # Color head: separate normalization and projection
            self.out_color = nn.Sequential(
                normalization(ch),
                nn.SiLU(),
                zero_module(conv_nd(dims, model_channels, self.color_channels, 3, padding=1)),
            )
        else:
            self.color_channels = 0
            self.out_geometry = None
            self.out_color = None

        # Standard single output head — produces all out_channels including any
        # feature channels that are part of the flow (geometry + color + features).
        self.out = nn.Sequential(
            normalization(ch),
            nn.SiLU(),
            zero_module(conv_nd(dims, model_channels, out_channels, 3, padding=1)),
        )

        if self.predict_codebook_ids:
            self.id_predictor = nn.Sequential(
            normalization(ch),
            conv_nd(dims, model_channels, n_embed, 1),
            #nn.LogSoftmax(dim=1)  # change to cross_entropy and produce non-normalized logits
        )

    def convert_to_fp16(self):
        """
        Convert the torso of the model to float16.
        """
        self.input_blocks.apply(convert_module_to_f16)
        self.middle_block.apply(convert_module_to_f16)
        self.output_blocks.apply(convert_module_to_f16)

    def convert_to_fp32(self):
        """
        Convert the torso of the model to float32.
        """
        self.input_blocks.apply(convert_module_to_f32)
        self.middle_block.apply(convert_module_to_f32)
        self.output_blocks.apply(convert_module_to_f32)

    def forward(self, x, timesteps=None, cond=None, coarse_geometry=None, context=None, **kwargs):
        inputs_to_concat = [x]
        
        if coarse_geometry is not None and self.geometry_channels > 0:
            coarse_upsampled = F.interpolate(coarse_geometry, size=x.shape[2:], mode='trilinear', align_corners=False)
            inputs_to_concat.insert(0, coarse_upsampled)
        
        if cond is not None:
            if "layout" in cond and cond["layout"] is not None:
                inputs_to_concat.append(cond["layout"])
            elif self.map_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.map_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
            
            if "outpaint_mask" in cond and cond["outpaint_mask"] is not None:
                inputs_to_concat.append(cond["outpaint_mask"])
                inputs_to_concat.append(cond["outpaint_latent"])
            elif self.outpainting_channels > 0:
                # Unconditional: mask=1 (generate everything), latent=0 (nothing known)
                outpaint_uncond = torch.zeros(x.shape[0], self.outpainting_channels, *x.shape[2:], device=x.device, dtype=torch.float32)
                outpaint_uncond[:, 0] = 1.0
                inputs_to_concat.append(outpaint_uncond)
            
            if "inpaint_mask" in cond and cond["inpaint_mask"] is not None:
                inputs_to_concat.append(cond["inpaint_mask"])
                inputs_to_concat.append(cond["inpaint_latent"])
            elif self.inpainting_channels > 0:
                # Unconditional: mask=1 (generate everything), latent=0 (nothing known)
                inpaint_uncond = torch.zeros(x.shape[0], self.inpainting_channels, *x.shape[2:], device=x.device, dtype=torch.float32)
                inpaint_uncond[:, 0] = 1.0
                inputs_to_concat.append(inpaint_uncond)
            
            # Handle micro conditioning - broadcast 6-dim vector to spatial grid
            if "micro" in cond and cond["micro"] is not None:
                micro = cond["micro"]  # [B, 6]
                micro_grid = micro[:, :, None, None, None].expand(-1, -1, *x.shape[2:])
                inputs_to_concat.append(micro_grid)
            elif self.micro_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.micro_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
            
            if "tags" in cond and cond["tags"] is not None:
                inputs_to_concat.append(cond["tags"])
            elif self.tag_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.tag_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
        else:
            if self.map_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.map_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
            if self.outpainting_channels > 0:
                outpaint_uncond = torch.zeros(x.shape[0], self.outpainting_channels, *x.shape[2:], device=x.device, dtype=torch.float32)
                outpaint_uncond[:, 0] = 1.0
                inputs_to_concat.append(outpaint_uncond)
            if self.inpainting_channels > 0:
                inpaint_uncond = torch.zeros(x.shape[0], self.inpainting_channels, *x.shape[2:], device=x.device, dtype=torch.float32)
                inpaint_uncond[:, 0] = 1.0
                inputs_to_concat.append(inpaint_uncond)
            if self.micro_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.micro_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
            if self.tag_channels > 0:
                inputs_to_concat.append(torch.zeros(x.shape[0], self.tag_channels, *x.shape[2:], device=x.device, dtype=torch.float32))
        
        x_input = torch.cat(inputs_to_concat, dim=1)
        
        if timesteps is not None:
            model_device = next(self.parameters()).device
            if timesteps.device != model_device:
                timesteps = timesteps.to(model_device)

        t_emb = timestep_embedding(timesteps, self.model_channels, repeat_only=False)
        emb_t = self.time_embed(t_emb)

        if coarse_geometry is not None and self.geo_embed is not None:
            emb_g = self.geo_embed(coarse_geometry)
            emb = emb_t + emb_g
        else:
            emb = emb_t

        if self.map_embed is not None:
            if cond is not None and "layout" in cond and cond["layout"] is not None:
                map_tensor = cond["layout"]
                emb_m = self.map_embed(map_tensor)
                emb = emb + emb_m

        while len(emb.shape) < len(x_input.shape):
            emb = emb[..., None]
        h = x_input
        hs = []
        for module in self.input_blocks:
            h = module(h, emb, context)
            hs.append(h)
        
        h = self.middle_block(h, emb, context)
        
        for module in self.output_blocks:
            skip = hs.pop()
            # Crop decoder features to match skip-connection spatial dims.
            # Upsample doubles ALL spatial dims (F.interpolate scale_factor=2),
            # but a dimension that was clamped to 1 by strided-conv downsampling
            # (e.g. height 4→2→1→1) will be doubled to 2, while the
            # corresponding encoder skip still sits at 1.  Cropping the
            # surplus voxels is the standard UNet fix for this asymmetry.
            if h.shape[2:] != skip.shape[2:]:
                h = h[:, :, :skip.shape[2], :skip.shape[3], :skip.shape[4]]
            h = torch.cat([h, skip], dim=1)
            h = module(h, emb, context)

        if self.predict_codebook_ids:
            h = self.id_predictor(h)
        else:
            # Use separate heads for geometry and color (only when use_separate_color_head=True)
            if self.use_separate_color_head:
                h_geometry = self.out_geometry(h)
                h_color = self.out_color(h)
                h = torch.cat([h_geometry, h_color], dim=1)
            else:
                h = self.out(h)
        
        return h

